------------------------------------------------------------
-- Smoking status (patient level)
-- Most recent record prior to infection event
-- Unknown = no smoking record
------------------------------------------------------------

;WITH smoking_events AS (
    SELECT
        P.Patient_ID,
        P.infect,
        P.event_date,

        med.EventDate AS smoking_event_date,

        CASE
            -- Never smoker
            WHEN snomed.ConceptID IN (
'8392000',
  '266919005',
  '43381005',
